-- Generated by: python -m tools.manage generate
-- Run in a NEW, empty database. No DROP statements.

CREATE TABLE account (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	username VARCHAR(40) NOT NULL, 
	password_hash VARCHAR(60) NOT NULL, 
	`role` VARCHAR(10) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_account_role CHECK (role IN ('admin','clerk')), 
	UNIQUE (username)
)CHARSET=utf8mb4 ENGINE=InnoDB;

CREATE TABLE customer (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(80) NOT NULL, 
	phone VARCHAR(30) NOT NULL, 
	address VARCHAR(200) NOT NULL, 
	PRIMARY KEY (id)
)CHARSET=utf8mb4 ENGINE=InnoDB;

CREATE TABLE product (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	sku VARCHAR(40) NOT NULL, 
	name VARCHAR(80) NOT NULL, 
	price NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_product_price CHECK (price > 0), 
	UNIQUE (sku)
)CHARSET=utf8mb4 ENGINE=InnoDB;

CREATE TABLE warehouse (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	name VARCHAR(80) NOT NULL, 
	PRIMARY KEY (id), 
	UNIQUE (name)
)CHARSET=utf8mb4 ENGINE=InnoDB;

CREATE TABLE sales_order (
	id INTEGER NOT NULL AUTO_INCREMENT, 
	request_key VARCHAR(36) NOT NULL, 
	customer_id INTEGER NOT NULL, 
	warehouse_id INTEGER NOT NULL, 
	created_by INTEGER NOT NULL, 
	status VARCHAR(12) NOT NULL, 
	created_at DATETIME NOT NULL, 
	PRIMARY KEY (id), 
	CONSTRAINT ck_order_status CHECK (status IN ('pending','shipped','cancelled')), 
	UNIQUE (request_key), 
	FOREIGN KEY(customer_id) REFERENCES customer (id), 
	FOREIGN KEY(warehouse_id) REFERENCES warehouse (id), 
	FOREIGN KEY(created_by) REFERENCES account (id)
)CHARSET=utf8mb4 ENGINE=InnoDB;

CREATE INDEX ix_order_customer_created ON sales_order (customer_id, created_at);

CREATE TABLE stock (
	warehouse_id INTEGER NOT NULL, 
	product_id INTEGER NOT NULL, 
	quantity INTEGER NOT NULL, 
	PRIMARY KEY (warehouse_id, product_id), 
	CONSTRAINT ck_stock_quantity CHECK (quantity >= 0), 
	FOREIGN KEY(warehouse_id) REFERENCES warehouse (id), 
	FOREIGN KEY(product_id) REFERENCES product (id)
)CHARSET=utf8mb4 ENGINE=InnoDB;

CREATE TABLE order_item (
	order_id INTEGER NOT NULL, 
	product_id INTEGER NOT NULL, 
	quantity INTEGER NOT NULL, 
	unit_price NUMERIC(10, 2) NOT NULL, 
	PRIMARY KEY (order_id, product_id), 
	CONSTRAINT ck_item_value CHECK (quantity > 0 AND unit_price > 0), 
	FOREIGN KEY(order_id) REFERENCES sales_order (id), 
	FOREIGN KEY(product_id) REFERENCES product (id)
)CHARSET=utf8mb4 ENGINE=InnoDB;

CREATE TABLE shipment (
	order_id INTEGER NOT NULL, 
	tracking_no VARCHAR(60) NOT NULL, 
	shipped_at DATETIME NOT NULL, 
	PRIMARY KEY (order_id), 
	FOREIGN KEY(order_id) REFERENCES sales_order (id), 
	UNIQUE (tracking_no)
)CHARSET=utf8mb4 ENGINE=InnoDB;
